function getDroughtMonStream(outStream) {
  var pass = new stream.PassThrough()

  req('http://droughtmonitor.unl.edu/data/shapefiles_m/USDM_' + dates.getDroughtMonDate() + '_M.zip')
  .pipe(pass)

  toJSON(pass).pipe(outStream)
}
